const conflict =
  statusCode === 409 ||
  String(body?.code || body?.errorCode || '').toUpperCase() === 'SLOT_UNAVAILABLE';

const appointmentId = body?.appointmentId ?? body?.id ?? null;
const s = $('Session With Patient').first().json;
const name = $('Set Patient Name').first().json.patientName;

return [{
  json: {
