    reply_to_patient:
      success
        ? `Your appointment has been booked successfully for ${s.appointmentDate} at ${s.selectedStartTime}.${appointmentId ? ` Appointment ID: ${appointmentId}.` : ''}`
        : conflict
          ? `Sorry, the ${s.selectedStartTime} slot was just booked by another patient. Let me check the remaining slots.`
          : `Sorry, I could not complete the booking. Please try another slot.`
  }
}];

const input = $('Parse Twilio Payload & QR Code').first()?.json || {};
const session = $('Session With Patient').first()?.json || {};
let doctors = [];
try {
  // Prefer doctors already fetched for clinic (no service filter)
  doctors = $('Fetch Clinic Doctors').all().map(i => ({ id: i.json.id, name: i.json.name, serviceId: i.json.serviceId || i.json.defaultServiceId || null }));
} catch (e) {
  try {
    doctors = $('Get Doctors For Service').all().map(i => ({ id: i.json.id, name: i.json.name, serviceId: i.json.serviceId || null }));
  } catch (e2) {}
}
const prompt = `Extract the patient's appointment selection. Return ONLY JSON.
Allowed types: DOCTOR, DATE, UNKNOWN.
Rules:
- Match DOCTOR only to the supplied doctors list (by name).
- Convert dates to YYYY-MM-DD (use currentDateTime Asia/Kolkata for relative dates like tomorrow).
- Do not invent values. Do not ask for or return SERVICE.
Output exactly: {"type":"DOCTOR|DATE|UNKNOWN","value":"string or null","doctorId":"string or null"}`;
const user = JSON.stringify({
  state: session.state,
  patientMessage: input.messageText,
  currentDateTime: new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
