const raw = $json || {};
const statusCode = Number(raw.statusCode ?? raw.status ?? 200);
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const parsed = $('Parse Twilio Payload & QR Code').first()?.json || {};

const clinicId = body.clinicId ?? parsed.clinicId ?? null;
const clinicName = body.clinicName || body.name || null;
const ok = statusCode >= 200 && statusCode < 300 && clinicId != null;

return [{
  json: {
    ok,
    statusCode,
    clinicId: clinicId != null ? Number(clinicId) : null,
    clinicName,
    whatsappNumber: parsed.whatsappNumber,
    patientToken: parsed.patientToken,
    qrType: 'CLINIC',
    errorMessage: ok ? null : (body.message || body.error || 'Invalid or expired clinic QR code.')
  }
}];

const input = $('Parse Twilio Payload & QR Code').first()?.json || {};
const session = $('Session With Patient').first()?.json || {};
const message = String(input.messageText || '').trim();

let doctors = [];
try {
  doctors = $('Fetch Clinic Doctors').all().map(i => i.json);
} catch (e) {
  doctors = [];
}

let matched = null;
if (/^\d+$/.test(message)) {
  const n = Number(message);
  if (n >= 1 && n <= doctors.length) matched = doctors[n - 1];
}
if (!matched && message) {
  const m = message.toLowerCase().replace(/^dr\.?\s+/, '').trim();
  matched = doctors.find(x => String(x.name || '').toLowerCase().replace(/^dr\.?\s+/, '').trim() === m)
    || doctors.find(x => String(x.name || '').toLowerCase().includes(m));
}

const canSelect = !session.doctorId || session.state === 'STARTED' || session.state === 'COLLECTING_DOCTOR';

if (matched && canSelect) {
  return [{
    json: {
      isDoctor: true,
      doctorId: matched.id,
      doctorName: matched.name,
      serviceId: matched.serviceId || matched.defaultServiceId || session.serviceId || null,
      state: 'COLLECTING_DATE',
      reply_to_patient: `Great! You've selected ${matched.name}. What date would you like? (e.g., 2026-09-15).`
    }
  }];
}

return [{ json: { isDoctor: false } }];
